      : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_RuleEngine,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_RuleEngine,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_RuleEnginePtr,
  );

  /// Evaluate image-decode style JS with binary `result`.
  ///
  /// - `input_base64`: encrypted image bytes (standard base64)
  /// - returns decrypted bytes as standard base64, or empty string on failure
  Future<String> evalBytesJs(
          {required String script,
          required String inputBase64,
          required String baseUrl,
          String? src}) =>
      RustLib.instance.api.crateApiRuleEngineRuleEngineEvalBytesJs(
          that: this,
          script: script,
          inputBase64: inputBase64,
          baseUrl: baseUrl,
          src: src);

  Future<BookInfo?> extractBookInfo(
          {required String html,
          required BookInfoRule rule,
          required String baseUrl}) =>
      RustLib.instance.api.crateApiRuleEngineRuleEngineExtractBookInfo(
          that: this, html: html, rule: rule, baseUrl: baseUrl);

  Future<List<BookItem>> extractBookList(
          {required String html,
          required SearchRule rule,
          required String baseUrl}) =>
      RustLib.instance.api.crateApiRuleEngineRuleEngineExtractBookList(
          that: this, html: html, rule: rule, baseUrl: baseUrl);

